public class DoveFlyState : State<Dove>
{
	private NumVarStatMod flyMoveSpeedMod;

	private ChaosQuickStopwatch flyTimer;

	private float maxFlyTime = 6f;

	public DoveFlyState(string stateName, FSM parentFSM, Dove parentEntity)
		: base(stateName, parentFSM, parentEntity)
	{
		flyMoveSpeedMod = new NumVarStatMod("FlyMoveSpeed", Random.Range(0.6f, 1.4f), 10, VarStatModType.Multiplicative);
	}

	public override void OnEnter()
	{
		parent.anim.Play("Fly");
		parent.spriteSorter.enabled = false;
		parent.spriteRenderer.sortingLayerName = "OverlayDoodad";
		parent.spriteRenderer.sortingOrder = 10;
		float num = 1f;
		float num2 = 1f;
		if (parent.closestTargetInfo != null)
		{
			if (parent.transform.position.y < parent.closestTargetInfo.transform.position.y)
			{
				num = -1f;
			}
			if (parent.transform.position.x < parent.closestTargetInfo.transform.position.x)
			{
				num2 = -1f;
			}
		}
		else
		{
			num = ((!(Random.value > 0.5f)) ? 1f : (-1f));
			num2 = ((!(Random.value > 0.5f)) ? 1f : (-1f));
		}
		parent.movement.moveVector = new Vector3(Random.Range(0.75f, 1f) * num2, Random.Range(0.25f, 0.66f) * num);
		parent.movement.moveSpeedStat.AddMod(flyMoveSpeedMod);
		parent.FaceTarget(parent.transform.position + (Vector3)parent.movement.moveVector, 2);
		flyTimer = new ChaosQuickStopwatch(maxFlyTime);
		flyTimer.IsRunning = true;
	}

	public override void Update()
		parent.anim.Play("Idle");
	}

	public override void Update()
	{
{
	base.Start();
	if (isMini)
	{
		attackSkillID = "NeutralMiniBlobAttack";
		animSpeedHandler.Modify(new NumVarStatMod("MiniBlob", 0.5f, 10, VarStatModType.Multiplicative), givenStatus: true);
		spriteRenderer.material.SetFloat("_PaletteIndex", 0f);
	}
	else
	{
		attackSkillID = "NeutralBlobAttack";
		if (!divide)
		{
			divide = CurrentDifficulty > 0;
		}
		if (divide)
		{
			dropLoot = false;
			spriteRenderer.material.SetFloat("_PaletteIndex", 1f);
		}
		else
		{
			health.healthStat.AddMod(new NumVarStatMod("NoDivide", 0.5f, 10, VarStatModType.Multiplicative, fillToNewMax: true));
		}
	}
	attack.gameObject.SetActive(value: false);
}

public override void Start()
{
	base.Start();
	if (!(DifficultyValue <= 0f))
	{
		speedupMod = new NumVarStatMod("DiffSpeedUp", DifficultyValue * 0.25f, 5, VarStatModType.Multiplicative);
		animSpeedHandler.Modify(speedupMod, givenStatus: true);
		movement.moveSpeedStat.Modify(speedupMod, addMod: true);
	}
}

	public override void Apply(VarStat<float> varStatToMod)
	{
		base.Apply(varStatToMod);
		if (modType == VarStatModType.Override || modType == VarStatModType.OverrideWithMods)
		{
			varStatToMod.ModifiedValue = modValue;
		}
		else
		{
			switch (modType)
			{
			case VarStatModType.Additive:
				varStatToMod.ModifiedValue += modValue;
				break;
			case VarStatModType.Multiplicative:
				ApplyMultiplicative(varStatToMod);
				break;
			case VarStatModType.LateMultiplicative:
				ApplyMultiplicative(varStatToMod);
				break;
			}
		}
		if (fillToNewMax)
		{
			varStatToMod.CurrentValue = varStatToMod.ModifiedValue;
		}
	}

	public new void Remove(VarStat<float> varStatToMod)
	{
		base.Apply(varStatToMod);
	}
}

